INSERT INTO `home_co` VALUES ('12', '3', ',2,3,', '公司简介', '', '', '', '', '', '', '', '<p style=\"text-indent: 2em;\">我司成立于2009年 ，经过12年多的努力与发展，现拥有经验丰富的电子元器件销售团队，具备优质稳定的货源保障，已具一定的规模及实力强大的关系网，并在香港设立仓库。公司经营范围，主营ST(意法）NXP,GD，TI等单片机以及周边驱动器IC，MOS管，电源管理芯片等 。产品广泛应用于民用、工业、军工等领域，深受广大客户的信赖。包括为客户提供产品配套技术支持的多元化的集成电路经销商。</p>\r\n<p style=\"text-indent: 2em;\">公司多年来在同行内已树立了良好的信誉，服务客户超15000家，我们将以更好的产品质量，更完善的售后服务，更优的产品价格，更强的技术支持，竭诚为您提供更好服务</p>\r\n<p>&nbsp;</p>', null, null, null, null, '', '', '', '0', '0', '0', '1', '0', '100', '127.0.0.1', 'zh-cn', '2025-02-18 11:47:26', null);
INSERT INTO `home_co` VALUES ('13', '8', ',7,8,', '联系我们', '', '', '', '', '', '', '', '<h3>深圳市森蓝微电子有限公司</h3>\r\n<p>联系我们：0755-21082640<br /><span style=\"color: #333333; font-family: 微软雅黑; background-color: #ffffff;\"><span style=\"color: #333333; font-family: 微软雅黑; background-color: #ffffff;\">客服QQ：3007726439<br /><br /></span></span></p>\r\n<p style=\"font-family: 微软雅黑; margin-top: 0px; margin-bottom: 0px; padding: 0px; color: #333333;\">工作时间：</p>\r\n<div style=\"font-family: 微软雅黑; margin: 0px; padding: 0px; border: 0px; color: #333333;\">周一至周五早上9:00-12：00&nbsp;&nbsp;下午13:30-18:00<br />\r\n<p style=\"margin-top: 0px; margin-bottom: 0px; padding: 0px;\">周六早上9:00-12：00&nbsp;&nbsp;下午13:00-17:00</p>\r\n</div>\r\n<p><br />地址：深圳市龙华新区民宝路淘景大厦12楼</p>', null, null, null, null, '', '', '', '0', '0', '0', '1', '0', '100', '127.0.0.1', 'zh-cn', '2025-02-22 10:02:43', null);
